cat > /etc/nginx/sites-enabled/default << 'EOF'
server {
    listen 80 default_server;
    listen [::]:80 default_server;

    server_name _;

    root /var/www/html;
    index index.html index.htm index.nginx-debian.html;

    location / {
        try_files $uri $uri/ =404;
    }
}
EOF
ngix -t 2>&1 && nginx || echo 'nginx starting'
sleep 1
netstat -tlnp 2>/dev/null | grep ':80' || ps aux | grep nginx

